import { ROLES, getRole } from "./roles.js";
import { PHASE_LABELS, compositionRoles } from "./game.js";
import { currentNightStep } from "./night.js";
import { tallyVotes } from "./voting.js";
import { escapeHtml, formatTime } from "./utils.js";

const icon = (name, classes = "h-5 w-5") => `<i data-lucide="${name}" aria-hidden="true" class="${classes}"></i>`;
export const ICONS = {
  moon: icon("moon-star"),
  users: icon("users"),
  menu: icon("menu"),
  arrow: icon("chevron-right"),
  plus: icon("plus"),
  back: icon("arrow-left"),
  check: icon("check"),
  clock: icon("timer"),
  download: icon("download"),
  home: icon("house"),
  settings: icon("settings-2"),
  skull: icon("skull"),
  trash: icon("trash-2"),
  undo: icon("undo-2"),
  note: icon("notebook-pen"),
  close: icon("x"),
  up: icon("arrow-up"),
  down: icon("arrow-down"),
  reset: icon("rotate-ccw"),
};

const btn = (label, action, variant = "primary", attrs = "") => {
  const styles = {
    primary: "bg-amberwood text-forest-950 hover:bg-[#d8aa59] shadow-lg shadow-black/15",
    secondary: "border border-white/15 bg-white/[.06] text-parchment hover:bg-white/[.10]",
    danger: "border border-red-800/60 bg-wolf/30 text-red-100 hover:bg-wolf/50",
    ghost: "text-stone-300 hover:bg-white/[.06] hover:text-white",
  };
  return `<button type="button" data-action="${action}" ${attrs} class="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition focus:outline-none focus:ring-2 focus:ring-amberwood/80 disabled:cursor-not-allowed disabled:opacity-40 ${styles[variant]}">${label}</button>`;
};
const field = "min-h-11 w-full rounded-xl border border-white/15 bg-black/20 px-3.5 py-2.5 text-parchment placeholder:text-stone-500 focus:border-amberwood/70 focus:outline-none focus:ring-2 focus:ring-amberwood/20";
const card = "rounded-2xl border border-white/10 bg-forest-900/85 shadow-glow";
const label = (text, forId = "") => `<label ${forId ? `for="${forId}"` : ""} class="mb-1.5 block text-sm font-medium text-stone-300">${text}</label>`;
const statusBadge = (alive) => `<span class="rounded-full border px-2.5 py-1 text-xs font-semibold ${alive ? "border-moss/30 bg-moss/10 text-[#bbd2b2]" : "border-red-800/50 bg-wolf/20 text-red-200"}">${alive ? "Vivant" : "Mort"}</span>`;
export const mjScript = (steps, variantIndex = 0) => `<div class="mb-5 rounded-xl border border-amberwood/25 bg-amberwood/[.07] p-4"><p class="text-xs font-semibold uppercase tracking-[.16em] text-amberwood">Déroulé du MJ</p><div class="${steps.length > 1 ? "mt-4" : "mt-3"} space-y-3">${steps.map(({ when, text, variants, action }) => {
  if (action) return `<div class="rounded-lg border border-white/10 bg-black/15 p-3"><p class="text-[11px] font-semibold uppercase tracking-[.14em] text-moss">Action du MJ</p><p class="mt-1 text-sm leading-relaxed text-stone-300">${action}</p></div>`;
  const selectedText = variants?.length ? variants[Math.abs(variantIndex) % variants.length] : text;
  return `<div>${when ? `<p class="mb-1 text-[11px] font-semibold uppercase tracking-wider text-stone-500">${when}</p>` : ""}<p class="font-display italic leading-relaxed text-parchment">« ${selectedText} »</p></div>`;
}).join("")}</div></div>`;

function logo(size = "normal") {
  return `<div class="flex items-center gap-3"><span class="grid ${size === "large" ? "h-14 w-14" : "h-10 w-10"} place-items-center rounded-2xl border border-amberwood/30 bg-amberwood/10 text-amberwood">${ICONS.moon}</span><div><p class="font-display ${size === "large" ? "text-2xl" : "text-lg"} font-semibold tracking-wide text-parchment">Werewolf Manager</p>${size === "large" ? '<p class="text-xs uppercase tracking-[.22em] text-moss">Maître du village</p>' : ""}</div></div>`;
}

function home(hasSave) {
  return `<main class="mist flex min-h-screen items-center justify-center px-5 py-12"><section class="w-full max-w-lg text-center">
    <div class="mb-10 flex justify-center">${logo("large")}</div>
    <h1 class="font-display text-4xl leading-tight text-white sm:text-5xl">Le village s’endort.<br><span class="text-amberwood">À vous de guider la nuit.</span></h1>
    <p class="mx-auto mt-5 max-w-md text-base leading-relaxed text-stone-300">Le tableau de bord privé du Maître du Jeu, de la préparation jusqu’à la victoire.</p>
    <div class="mx-auto mt-10 grid max-w-sm gap-3">${btn(`${ICONS.plus} Nouvelle partie`, "new-game")} ${hasSave ? btn(`${ICONS.arrow} Reprendre la partie`, "resume-game", "secondary") : ""} ${btn("Importer une partie", "import-game", "ghost")} ${btn("Paramètres", "open-settings", "ghost")}</div>
  </section></main>`;
}

function setup(game) {
  const count = game.players.length;
  const rolesCount = game.composition.werewolf + game.composition.villager + game.composition.specials.length;
  const distinctRoleCount = Number(game.composition.werewolf > 0) + Number(game.composition.villager > 0) + game.composition.specials.length;
  const werewolfRole = getRole("werewolf");
  const villagerRole = getRole("villager");
  const specialVillageRoles = ROLES.filter((role) => role.team === "village" && role.id !== "villager");
  const campSeparator = (name, tone) => `<div role="separator" aria-label="${name}" class="flex items-center gap-3 py-2"><span class="h-px flex-1 ${tone === "wolf" ? "bg-wolf/60" : "bg-moss/40"}"></span><div class="flex items-center gap-2 rounded-full border px-3 py-1.5 ${tone === "wolf" ? "border-wolf/50 bg-wolf/10 text-red-200" : "border-moss/30 bg-moss/10 text-[#bbd2b2]"}"><span class="h-1.5 w-1.5 rounded-full ${tone === "wolf" ? "bg-red-400" : "bg-moss"}"></span><span class="text-xs font-semibold uppercase tracking-[.14em]">${name}</span></div><span class="h-px flex-1 ${tone === "wolf" ? "bg-wolf/60" : "bg-moss/40"}"></span></div>`;
  return `<div class="min-h-screen"><header class="border-b border-white/10 px-4 py-4 sm:px-6"><div class="mx-auto flex max-w-6xl items-center justify-between">${logo()}${btn("Quitter", "go-home", "ghost")}</div></header>
  <main class="mx-auto max-w-6xl px-4 py-7 sm:px-6 sm:py-10">
    <div class="mb-8"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Nouvelle partie</p><h1 class="mt-2 font-display text-3xl text-white">Préparez votre village</h1><p class="mt-2 text-stone-400">Ajoutez les joueurs, puis composez les rôles. Tout reste modifiable avant le lancement.</p></div>
    <div class="grid gap-6 lg:grid-cols-[1.05fr_.95fr]">
      <section class="${card} p-5 sm:p-6"><div class="mb-5 flex items-center justify-between"><div><h2 class="text-lg font-semibold text-white">1. Joueurs</h2><p class="text-sm text-stone-400">${count} participant${count > 1 ? "s" : ""}</p></div>${btn("Noms temporaires", "fill-players", "ghost")}</div>
        <div class="mb-5">${label("Nom de la partie", "game-name")}<input id="game-name" data-change="game-name" value="${escapeHtml(game.name)}" class="${field}"></div>
        <form data-form="add-player" class="mb-4 flex gap-2"><label class="sr-only" for="player-name">Nom du joueur</label><input id="player-name" name="name" autocomplete="off" placeholder="Nom du joueur" class="${field}">${btn(`${ICONS.plus}<span class="sr-only sm:not-sr-only">Ajouter</span>`, "submit-player")}</form>
        <div class="space-y-2">${game.players.length ? game.players.map((player, index) => `<div class="flex items-center gap-2 rounded-xl border border-white/10 bg-black/15 p-2"><span class="w-7 text-center text-xs text-stone-500">${index + 1}</span><input aria-label="Nom de ${escapeHtml(player.name)}" data-player-name="${player.id}" value="${escapeHtml(player.name)}" class="min-w-0 flex-1 bg-transparent px-2 py-2 text-sm text-parchment outline-none focus:ring-2 focus:ring-amberwood/30 rounded-lg"><button data-action="move-player" data-id="${player.id}" data-direction="up" aria-label="Monter ${escapeHtml(player.name)}" class="grid h-10 w-10 place-items-center rounded-lg text-stone-400 hover:bg-white/5 disabled:opacity-20" ${index === 0 ? "disabled" : ""}>${ICONS.up}</button><button data-action="move-player" data-id="${player.id}" data-direction="down" aria-label="Descendre ${escapeHtml(player.name)}" class="grid h-10 w-10 place-items-center rounded-lg text-stone-400 hover:bg-white/5 disabled:opacity-20" ${index === count - 1 ? "disabled" : ""}>${ICONS.down}</button><button data-action="remove-player" data-id="${player.id}" aria-label="Supprimer ${escapeHtml(player.name)}" class="grid h-10 w-10 place-items-center rounded-lg text-red-300 hover:bg-wolf/20">${ICONS.close}</button></div>`).join("") : '<div class="rounded-xl border border-dashed border-white/15 px-4 py-8 text-center text-sm text-stone-500">Ajoutez au moins 5 joueurs pour commencer.</div>'}</div>
        ${count > 1 ? `<div class="mt-4">${btn("Mélanger l’ordre", "shuffle-players", "ghost")}</div>` : ""}
      </section>
      <section class="${card} p-5 sm:p-6"><div class="mb-5 flex items-start justify-between gap-3"><div><h2 class="text-lg font-semibold text-white">2. Composition</h2><p class="text-sm text-stone-400">Suggestion modifiable librement</p></div>${btn("Appliquer la recommandation", "recommend-roles", "secondary")}</div>
        <div class="mb-5 grid grid-cols-2 gap-3"><div class="rounded-xl bg-black/20 p-4"><p class="text-xs uppercase tracking-wider text-stone-500">Joueurs</p><p class="mt-1 text-2xl font-semibold">${count}</p></div><div class="rounded-xl bg-black/20 p-4"><p class="text-xs uppercase tracking-wider text-stone-500">Rôles différents</p><p class="mt-1 text-2xl font-semibold text-[#bbd2b2]">${distinctRoleCount}</p></div></div>
        <div class="space-y-2">
          ${campSeparator("Camp des Loups", "wolf")}
          <div class="flex items-center gap-3 rounded-xl border border-wolf/40 bg-wolf/10 p-3"><span class="text-red-300">${werewolfRole.icon}</span><div class="min-w-0 flex-1"><p class="font-medium">${werewolfRole.name}</p><p class="text-xs text-stone-500">Se réveillent ensemble pendant la nuit</p></div><input type="number" min="0" max="${count}" data-role-count="werewolf" value="${game.composition.werewolf}" aria-label="Nombre de Loups-Garous" class="${field} !w-20 text-center"></div>
          ${campSeparator("Camp du Village", "village")}
          <div class="flex items-center gap-3 rounded-xl border border-white/10 p-3"><span class="text-moss">${villagerRole.icon}</span><div class="min-w-0 flex-1"><p class="font-medium">${villagerRole.name}</p><p class="text-xs text-stone-500">Complète automatiquement la composition</p></div><span class="rounded-lg bg-white/5 px-3 py-2 font-semibold">${game.composition.villager}</span></div>
          ${specialVillageRoles.map((role) => `<label class="flex cursor-pointer items-center gap-3 rounded-xl border border-white/10 p-3 transition hover:bg-white/[.03]"><span class="text-amberwood">${role.icon}</span><span class="min-w-0 flex-1"><span class="block font-medium">${role.name}</span><span class="block truncate text-xs text-stone-500">${role.description}</span></span><input type="checkbox" data-special-role="${role.id}" class="h-5 w-5 rounded border-white/20 bg-black/20 text-amberwood focus:ring-amberwood" ${game.composition.specials.includes(role.id) ? "checked" : ""}></label>`).join("")}
        </div>
        ${rolesCount !== count ? `<div class="mt-5 rounded-xl border border-amberwood/30 bg-amberwood/10 p-3 text-sm text-amber-200">Écart : ${Math.abs(count - rolesCount)} rôle${Math.abs(count - rolesCount) > 1 ? "s" : ""}. Ajustez la composition.</div>` : ""}
        <div class="mt-5">${btn(`Continuer vers l’attribution ${ICONS.arrow}`, "go-distribution", "primary", rolesCount !== count || count < 5 ? "disabled" : "")}</div>
      </section>
    </div>
  </main></div>`;
}

function manualAssignmentEditor(game, selectedRoleId) {
  const requiredCounts = compositionRoles(game).reduce((counts, roleId) => ({ ...counts, [roleId]: (counts[roleId] || 0) + 1 }), {});
  const assignedCounts = game.players.reduce((counts, player) => player.roleId ? ({ ...counts, [player.roleId]: (counts[player.roleId] || 0) + 1 }) : counts, {});
  const configuredRoles = [getRole("werewolf"), ...ROLES.filter((role) => role.id !== "werewolf")].filter((role) => requiredCounts[role.id]);
  const remainingTotal = game.players.filter((player) => !player.roleId).length;
  return `<section class="${card} overflow-hidden"><div class="flex flex-wrap items-start justify-between gap-3 border-b border-white/10 px-5 py-4 sm:px-6"><div><h2 class="font-semibold text-white">Attribution manuelle</h2><p class="mt-1 text-sm text-stone-400">Glissez un rôle sur un joueur. Sur mobile, touchez d’abord le rôle puis le joueur.</p></div><div class="flex flex-wrap gap-2">${game.players.some((player) => player.roleId) ? btn("Réinitialiser les rôles", "reset-role-assignments", "ghost") : ""}${btn("Attribution aléatoire", game.players.some((player) => player.roleId) ? "reassign-roles" : "assign-roles", "secondary")}</div></div><div class="grid gap-5 p-4 sm:p-6 lg:grid-cols-[.72fr_1.28fr]"><div><div class="mb-3 flex items-center justify-between"><h3 class="text-sm font-semibold uppercase tracking-[.14em] text-stone-400">Rôles disponibles</h3><span class="text-xs text-stone-500">${remainingTotal} restant${remainingTotal > 1 ? "s" : ""}</span></div><div class="grid grid-cols-2 gap-2 lg:grid-cols-1">${configuredRoles.map((role) => { const remaining = Math.max(0, requiredCounts[role.id] - (assignedCounts[role.id] || 0)); const selected = selectedRoleId === role.id; return `<button type="button" draggable="${remaining > 0}" data-drag-role="${role.id}" data-action="select-manual-role" data-role-id="${role.id}" ${remaining === 0 ? "disabled" : ""} aria-pressed="${selected}" class="flex min-h-14 items-center gap-3 rounded-xl border p-3 text-left opacity-100 transition focus:outline-none focus:ring-2 focus:ring-amberwood/60 disabled:cursor-not-allowed disabled:opacity-100 ${selected ? "border-amberwood bg-amberwood/10" : role.team === "wolves" ? "border-wolf/40 bg-wolf/10 hover:border-red-700" : "border-white/10 bg-black/10 hover:border-moss/40"}"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-lg ${role.team === "wolves" ? "bg-wolf/20 text-red-300" : "bg-moss/10 text-moss"}">${role.icon}</span><span class="min-w-0 flex-1"><span class="block truncate text-sm font-semibold text-white">${role.name}</span><span class="block text-xs text-stone-500">${remaining} disponible${remaining > 1 ? "s" : ""}</span></span></button>`; }).join("")}</div></div><div><h3 class="mb-3 text-sm font-semibold uppercase tracking-[.14em] text-stone-400">Joueurs</h3><div class="space-y-2">${game.players.map((player) => { const role = player.roleId ? getRole(player.roleId) : null; return `<div data-role-dropzone data-player-id="${player.id}" data-action="assign-selected-role" role="button" tabindex="0" aria-label="Attribuer un rôle à ${escapeHtml(player.name)}" class="group flex min-h-16 items-center gap-3 rounded-xl border border-dashed p-3 transition focus:outline-none focus:ring-2 focus:ring-amberwood/60 ${role ? role.team === "wolves" ? "border-wolf/50 bg-wolf/10" : "border-moss/25 bg-moss/[.06]" : selectedRoleId ? "border-amberwood/50 bg-amberwood/[.06] hover:bg-amberwood/10" : "border-white/15 bg-black/10 hover:border-white/30"}"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl ${role ? role.team === "wolves" ? "bg-wolf/20 text-red-300" : "bg-moss/10 text-moss" : "bg-white/[.04] text-stone-600"}">${role ? role.icon : ICONS.plus}</span><span class="min-w-0 flex-1"><span class="block truncate font-semibold text-white">${escapeHtml(player.name)}</span><span class="block text-sm ${role ? "text-stone-300" : selectedRoleId ? "text-amber-200" : "text-stone-500"}">${role ? role.name : selectedRoleId ? `Déposer ${getRole(selectedRoleId).name} ici` : "Glissez ou sélectionnez un rôle"}</span></span>${role ? `<button type="button" data-action="clear-manual-role" data-id="${player.id}" aria-label="Retirer le rôle de ${escapeHtml(player.name)}" class="grid h-10 w-10 shrink-0 place-items-center rounded-lg text-stone-400 hover:bg-black/20 hover:text-red-200">${ICONS.close}</button>` : ""}</div>`; }).join("")}</div></div></div>${remainingTotal === 0 ? `<div class="flex justify-end border-t border-white/10 px-5 py-4 sm:px-6">${btn("Lancer la première nuit", "launch-game", "primary")}</div>` : ""}</section>`;
}

function distribution(game, selectedRoleId = null) {
  return `<div class="min-h-screen"><header class="border-b border-white/10 px-4 py-4"><div class="mx-auto flex max-w-5xl items-center justify-between">${logo()}${btn(`${ICONS.back} Configuration`, "back-setup", "ghost")}</div></header><main class="mx-auto max-w-5xl px-4 py-8 sm:px-6">
    <div class="mb-7"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Attribution MJ</p><h1 class="mt-2 font-display text-3xl text-white">Attribuez les rôles</h1><p class="mt-2 text-stone-400">Cet écran contient les informations secrètes de la partie et reste réservé au Maître du Jeu.</p></div>
    ${manualAssignmentEditor(game, selectedRoleId)}
  </main></div>`;
}

function gameHeader(game) {
  return `<header class="sticky top-0 z-30 border-b border-white/10 bg-forest-950/95 px-4 py-3 backdrop-blur"><div class="mx-auto flex max-w-7xl items-center gap-3"><div class="hidden sm:block">${logo()}</div><button data-action="game-home" class="font-display text-lg font-semibold sm:hidden">Werewolf</button><div class="h-8 w-px bg-white/10"></div><div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold text-white">${escapeHtml(game.name)}</p><p class="truncate text-xs text-amberwood">${PHASE_LABELS[game.phase]}</p></div><div class="hidden items-center gap-2 md:flex">${btn("Annuler", "undo", "ghost")}</div>${btn(ICONS.menu, "toggle-menu", "secondary", 'aria-label="Ouvrir le menu"')}</div></header>`;
}

function stats(game) {
  const alive = game.players.filter((player) => player.alive);
  const wolves = alive.filter((player) => player.team === "wolves");
  return `<div class="grid grid-cols-2 gap-3 sm:grid-cols-4"><div class="rounded-xl border border-white/10 bg-black/15 p-3"><p class="text-xs text-stone-500">Temps</p><p class="mt-1 font-semibold">${game.phase === "night" || game.phase === "night-resolution" ? `Nuit ${game.night}` : `Jour ${game.day}`}</p></div><div class="rounded-xl border border-white/10 bg-black/15 p-3"><p class="text-xs text-stone-500">Vivants</p><p class="mt-1 font-semibold">${alive.length}</p></div><div class="rounded-xl border border-white/10 bg-black/15 p-3"><p class="text-xs text-stone-500">Morts</p><p class="mt-1 font-semibold">${game.players.length - alive.length}</p></div><div class="rounded-xl border border-white/10 bg-black/15 p-3"><p class="text-xs text-stone-500">Loups vivants</p><p class="mt-1 font-semibold text-red-200">${wolves.length}</p></div></div>`;
}

function playerCards(game) {
  return `<div class="space-y-2">${game.players.map((player) => { const role = getRole(player.roleId); const lover = game.relationships.find((link) => link.type === "lovers" && link.playerIds.includes(player.id)); return `<article class="rounded-xl border ${player.alive ? "border-white/10 bg-black/10" : "border-red-950/50 bg-black/25 opacity-70"} p-3"><div class="flex items-center gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl ${role.team === "wolves" ? "bg-wolf/20 text-red-300" : "bg-moss/10 text-moss"}">${role.icon}</span><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><h3 class="truncate font-semibold text-white">${escapeHtml(player.name)}</h3>${statusBadge(player.alive)}${lover ? '<span class="rounded-full border border-amberwood/30 bg-amberwood/10 px-2 py-1 text-[11px] text-amber-200">Amoureux</span>' : ""}</div><p class="mt-1 text-sm text-stone-400">${role.name}</p>${!player.alive ? `<p class="mt-1 text-xs text-red-200">${escapeHtml(player.deathCause || "Cause inconnue")}</p>` : ""}</div><button data-action="player-menu" data-id="${player.id}" aria-label="Actions pour ${escapeHtml(player.name)}" class="grid h-11 w-11 place-items-center rounded-xl text-stone-400 hover:bg-white/5">${ICONS.menu}</button></div></article>`; }).join("")}</div>`;
}

function nightPanel(game) {
  if (!game.pendingNight) return `<section class="${card} p-6"><div class="text-center"><div class="mx-auto grid h-14 w-14 place-items-center rounded-full bg-amberwood/10 text-amberwood">${ICONS.moon}</div><h2 class="mt-4 text-xl font-semibold text-white">Nuit ${game.night}</h2></div><div class="mt-5">${mjScript([{ variants: ["La nuit tombe sur le village. Les habitants regagnent leur demeure et ferment les yeux. Peu à peu, le village s’endort dans un silence profond.", "Le soleil disparaît derrière les collines et l’obscurité enveloppe le village. Habitants, fermez les yeux : la nuit commence et nul ne doit voir ce qui rôde dans l’ombre."] }, { action: "Vérifiez que tous les joueurs ont bien fermé les yeux avant de lancer les actions nocturnes." }], game.night - 1)}</div><div class="mt-6 text-center">${btn("Tous les joueurs ont les yeux fermés", "start-night")}</div></section>`;
  const step = currentNightStep(game);
  if (!step) return "";
  const role = getRole(step.roleId);
  const alive = game.players.filter((player) => player.alive);
  const options = (filter = () => true) => `<option value="">Choisir un joueur</option>${alive.filter(filter).map((player) => `<option value="${player.id}">${escapeHtml(player.name)}</option>`).join("")}`;
  let action = "";
  let continueLabel = "Valider et continuer";
  let wakeLabel = `Réveillez ${role.name}`;
  if (step.actionType === "wolves") {
    wakeLabel = "Réveillez les Loups-Garous";
    continueLabel = "Les Loups se sont rendormis";
    action = `${mjScript([{ when: "Pour les réveiller", variants: ["Au cœur de la nuit, les Loups-Garous se réveillent et ouvrent les yeux sans un bruit. Ils se reconnaissent, puis désignent ensemble la victime qu’ils souhaitent dévorer cette nuit.", "Tandis que le village dort, les créatures de la meute ouvrent les yeux. Loups-Garous, reconnaissez vos semblables et choisissez en silence l’habitant qui ne verra peut-être pas l’aube."] }, { action: "Laissez les Loups-Garous se reconnaître et se mettre d’accord. Observez leur choix, puis sélectionnez leur victime dans la liste ci-dessous." }, { when: "Lorsque la victime est sélectionnée", variants: ["Les Loups-Garous ont choisi leur victime. Ils referment les yeux et se rendorment dans l’ombre.", "La meute a pris sa décision. Loups-Garous, effacez toute trace de votre présence, fermez les yeux et laissez de nouveau régner le silence."] }, { action: "Vérifiez que tous les Loups-Garous ont refermé les yeux avant de continuer." }], game.night - 1)}${label("Victime désignée", "night-target")}<select id="night-target" class="${field}">${options((player) => game.settings.wolvesCanTargetWolf || player.team !== "wolves")}</select>`;
  }
  if (step.actionType === "seer") {
    wakeLabel = "Réveillez la Voyante";
    continueLabel = "Révéler l’information à la Voyante";
    action = `${mjScript([{ variants: ["La Voyante se réveille et entrouvre les portes de l’invisible. Voyante, désigne en silence le joueur dont tu souhaites découvrir la véritable identité.", "Les brumes du sommeil s’écartent devant la Voyante. Ouvre les yeux et désigne l’habitant dont tu veux sonder l’âme cette nuit."] }, { action: "Attendez que la Voyante ouvre les yeux et désigne un joueur. Sélectionnez ce joueur ci-dessous, puis révélez-lui son identité." }], game.night - 1)}${label("Joueur observé", "night-target")}<select id="night-target" class="${field}">${options()}</select><div id="seer-result" class="mt-3 hidden rounded-xl border border-amberwood/30 bg-amberwood/10 p-4"></div>`;
  }
  if (step.actionType === "cupid") {
    wakeLabel = "Réveillez Cupidon";
    continueLabel = "Les amoureux se sont reconnus";
    action = `${mjScript([{ when: "Pour réveiller Cupidon", variants: ["Cupidon se réveille. Cette nuit, il va lier deux âmes qui partageront désormais le même destin. Cupidon, désigne en silence les deux joueurs que tu choisis.", "Dans le secret de cette première nuit, Cupidon ouvre les yeux et prépare ses flèches. Désigne les deux cœurs que tu veux unir jusqu’à ce que la mort les sépare."] }, { action: "Attendez que Cupidon ouvre les yeux et désigne deux joueurs. Sélectionnez ces deux amoureux dans les listes ci-dessous." }, { when: "Après avoir sélectionné les amoureux", variants: ["Cupidon a décoché ses flèches. Il referme les yeux et se rendort.", "Les flèches de Cupidon ont trouvé leur cible. Cupidon peut maintenant fermer les yeux et se rendormir."] }, { action: "Attendez que Cupidon ait refermé les yeux. Touchez ensuite discrètement chacun des deux amoureux pour leur signaler de se réveiller." }, { when: "Une fois les amoureux touchés", variants: ["Les deux amoureux se réveillent maintenant, se découvrent et se reconnaissent en silence.", "Que les deux âmes désormais liées ouvrent les yeux et découvrent le visage de l’être qui partage leur destin."] }, { action: "Laissez aux amoureux quelques secondes pour se reconnaître, sans parler." }, { when: "Après qu’ils se sont reconnus", variants: ["Les amoureux connaissent désormais leur moitié. Ils referment les yeux et se rendorment.", "Le pacte des amoureux est scellé. Emportez ce secret avec vous, refermez les yeux et replongez dans la nuit."] }, { action: "Vérifiez que les amoureux ont refermé les yeux avant de continuer." }], game.night - 1)}<div class="grid gap-3 sm:grid-cols-2"><div>${label("Premier amoureux", "cupid-first")}<select id="cupid-first" class="${field}">${options()}</select></div><div>${label("Second amoureux", "cupid-second")}<select id="cupid-second" class="${field}">${options()}</select></div></div>`;
  }
  if (step.actionType === "witch") {
    const witch = game.players.find((player) => player.alive && player.roleId === "witch");
    const victim = game.players.find((player) => player.id === game.pendingNight.actions.wolves?.targetId);
    const life = !witch.effects.includes("life-potion-used"), death = !witch.effects.includes("death-potion-used");
    const selfForbidden = victim?.id === witch.id && !game.settings.witchCanSaveSelf;
    wakeLabel = "Réveillez la Sorcière";
    continueLabel = "La Sorcière s’est rendormie";
    action = `${mjScript([{ when: "Pour la réveiller", variants: ["La Sorcière se réveille. Dans ses potions sommeillent le pouvoir de sauver une vie et celui d’en condamner une autre.", "Au fond de sa demeure, la Sorcière ouvre les yeux et contemple ses deux précieux breuvages : l’un peut arracher une âme à la mort, l’autre peut l’y précipiter."] }, { action: `Attendez que la Sorcière ouvre les yeux, puis montrez-lui silencieusement la victime des Loups : <strong class="text-stone-200">${victim ? escapeHtml(victim.name) : "aucune"}</strong>.` }, { when: "Après lui avoir montré la victime", variants: ["Sorcière, souhaites-tu utiliser ta potion de vie pour sauver cette victime ? Souhaites-tu employer ta potion de mort contre un autre habitant ?", "Sorcière, veux-tu offrir ton antidote à la victime de la meute ? Désires-tu verser ton poison dans la coupe d’un autre habitant ?"] }, { action: "Laissez la Sorcière décider en silence, puis reportez ci-dessous son choix pour chaque potion." }, { when: "Après avoir enregistré sa décision", variants: ["La Sorcière a fait son choix. Elle range ses potions, referme les yeux et se rendort.", "Le destin est scellé. La Sorcière dissimule ses fioles, ferme les yeux et retourne au silence de la nuit."] }, { action: "Vérifiez que la Sorcière a refermé les yeux avant de continuer." }], game.night - 1)}<label class="flex items-center gap-3 rounded-xl border border-white/10 p-3 ${!life || !victim || selfForbidden ? "opacity-50" : ""}"><input id="witch-save" type="checkbox" class="h-5 w-5" ${!life || !victim || selfForbidden ? "disabled" : ""}><span>Sauver la victime <small class="block text-stone-500">${selfForbidden ? "Règle d’auto-sauvetage désactivée" : `Potion ${life ? "disponible" : "utilisée"}`}</small></span></label><div class="mt-3">${label(`Empoisonner un joueur — potion ${death ? "disponible" : "utilisée"}`, "witch-kill")}<select id="witch-kill" class="${field}" ${!death ? "disabled" : ""}><option value="">N’empoisonner personne</option>${alive.filter((player) => player.roleId !== "witch").map((player) => `<option value="${player.id}">${escapeHtml(player.name)}</option>`).join("")}</select></div>`;
  }
  return `<section class="${card} overflow-hidden"><div class="border-b border-white/10 px-5 py-3 text-sm text-stone-400">Étape ${game.pendingNight.index + 1} sur ${game.pendingNight.steps.length}</div><div class="p-5 sm:p-6"><div class="mb-5 flex items-center gap-3"><span class="grid h-12 w-12 place-items-center rounded-xl bg-amberwood/10 text-amberwood">${role.icon}</span><div><p class="text-xs uppercase tracking-[.16em] text-stone-500">Action du MJ</p><h2 class="text-xl font-semibold text-white">${wakeLabel}</h2></div></div>${action}<div class="mt-6">${btn(continueLabel, "validate-night")}</div></div></section>`;
}

function nightResolution(game) {
  const summary = game.pendingNight?.summary;
  if (!summary) return `<section class="${card} p-6"><p>Le bilan de la nuit n’est pas disponible.</p></section>`;
  const name = (id) => game.players.find((player) => player.id === id)?.name || "Personne";
  return `<section class="${card} p-5 sm:p-6"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Résolution de la nuit</p><h2 class="mt-2 font-display text-2xl text-white">Préparez votre annonce</h2><p class="mt-2 text-stone-300">Consultez ce bilan sans le montrer aux joueurs. Vérifiez les conséquences, puis passez au réveil du village.</p><dl class="mt-6 space-y-3 text-sm"><div class="flex justify-between gap-4 border-b border-white/10 pb-3"><dt class="text-stone-400">Victime des Loups</dt><dd class="font-semibold">${summary.wolfTarget ? escapeHtml(name(summary.wolfTarget)) : "Aucune"}</dd></div><div class="flex justify-between gap-4 border-b border-white/10 pb-3"><dt class="text-stone-400">Sauvée par la Sorcière</dt><dd class="font-semibold">${summary.saved ? "Oui" : "Non"}</dd></div><div class="flex justify-between gap-4 border-b border-white/10 pb-3"><dt class="text-stone-400">Empoisonné</dt><dd class="font-semibold">${summary.poisoned ? escapeHtml(name(summary.poisoned)) : "Personne"}</dd></div><div class="pt-2"><dt class="text-stone-400">Morts finales</dt><dd class="mt-2 text-lg font-semibold text-red-200">${summary.deathIds.length ? summary.deathIds.map((id) => escapeHtml(name(id))).join(", ") : "Aucune mort"}</dd></div></dl><div class="mt-7">${btn("Passer au réveil du village", "apply-night")}</div></section>`;
}

function phasePanel(game) {
  if (game.phase === "night") return nightPanel(game);
  if (game.phase === "night-resolution") return nightResolution(game);
  if (game.phase === "wake") {
    const deaths = game.wakeSummary?.deathIds.map((id) => game.players.find((player) => player.id === id)?.name).filter(Boolean) || [];
    const deathNames = new Intl.ListFormat("fr", { style: "long", type: "conjunction" }).format(deaths.map(escapeHtml));
    const wakeSpeechVariants = deaths.length === 0
      ? ["Le jour se lève sur le village. Habitants, ouvrez les yeux. Cette nuit fut paisible : personne n’a perdu la vie.", "Les premières lueurs de l’aube traversent le village. Ouvrez les yeux, habitants : malgré les ombres de la nuit, vous êtes tous encore en vie."]
      : deaths.length === 1
        ? [`Le jour se lève sur le village. Habitants, ouvrez les yeux. Mais cette nuit, nous avons perdu ${deathNames}.`, `L’aube se lève, mais tous ne contempleront pas sa lumière. Habitants, ouvrez les yeux : ${deathNames} ne se réveillera pas.`]
        : [`Le jour se lève sur le village. Habitants, ouvrez les yeux. Cette nuit, le village pleure la disparition de ${deathNames}.`, `Le silence de la nuit laisse place à une terrible découverte. Ouvrez les yeux, habitants : ${deathNames} ont perdu la vie avant l’aube.`];
    return `<section class="${card} p-6"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Le village se réveille</p><h2 class="mt-2 font-display text-2xl text-white">${deaths.length ? `${deaths.length} mort${deaths.length > 1 ? "s" : ""} cette nuit` : "Le village est intact"}</h2><div class="mt-5">${mjScript([{ variants: wakeSpeechVariants }, { action: "Attendez que tous les joueurs aient ouvert les yeux. Laissez-les réagir à l’annonce, puis ouvrez la phase de discussion." }], game.night - 1)}</div><div class="mt-6">${btn("Le résultat est annoncé", "next-phase")}</div></section>`;
  }
  if (game.phase === "discussion") return `<section class="${card} p-6"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Jour ${game.day}</p><h2 class="mt-2 font-display text-2xl text-white">Le village débat</h2><div class="mt-5">${mjScript([{ variants: ["Habitants du village, le temps est venu de débattre. Partagez vos soupçons, défendez-vous et tentez de démasquer les Loups-Garous qui se cachent parmi vous.", "Le jour vous rend la parole. Observez vos voisins, confrontez vos récits et écoutez vos instincts : les Loups-Garous sont peut-être assis juste à côté de vous."] }, { action: "Laissez les joueurs échanger. Prenez vos notes et utilisez le chronomètre si nécessaire. Passez au vote lorsque le débat est terminé." }], game.day - 1)}</div><div class="mt-5 flex flex-wrap gap-2">${[60,120,180,300].map((time) => btn(`${time / 60} min`, "set-timer", "secondary", `data-seconds="${time}"`)).join("")}</div><div class="mt-3 flex max-w-xs gap-2"><label class="sr-only" for="custom-timer">Durée personnalisée en minutes</label><input id="custom-timer" type="number" min="1" max="60" placeholder="Minutes" class="${field}">${btn("Appliquer", "set-custom-timer", "secondary")}</div><div class="mt-6">${btn("Passer au vote", "next-phase")}</div></section>`;
  if (game.phase === "vote") return votePanel(game);
  if (game.phase === "resolution") {
    const eliminated = game.players.find((player) => player.id === game.vote.selected);
    const resolutionSpeechVariants = eliminated
      ? [`Le village a rendu son verdict : ${escapeHtml(eliminated.name)} doit quitter le village. La nuit va bientôt tomber. Chacun regagne sa place et se prépare à fermer les yeux.`, `Les voix ont parlé et le sort de ${escapeHtml(eliminated.name)} est scellé. Que chacun médite ce choix, car déjà les ombres s’allongent et une nouvelle nuit approche.`]
      : ["Le village a rendu son verdict. La nuit va bientôt tomber. Chacun regagne sa place et se prépare à fermer les yeux.", "Le vote est terminé. Gardez-en les conséquences à l’esprit : le soleil décline déjà et le village devra bientôt affronter une nouvelle nuit."];
    return `<section class="${card} p-6"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Résolution</p><h2 class="mt-2 font-display text-2xl text-white">Le vote est appliqué</h2><div class="mt-5">${mjScript([{ variants: resolutionSpeechVariants }, { action: "Traitez les éventuels pouvoirs déclenchés par l’élimination. Demandez ensuite à tous les joueurs de fermer les yeux avant de passer à la nuit suivante." }], game.day - 1)}</div><div class="mt-6">${btn("Commencer la nuit suivante", "next-phase")}</div></section>`;
  }
  return "";
}

function votePanel(game) {
  const alive = game.players.filter((player) => player.alive);
  const result = tallyVotes(game);
  const opts = `<option value="">Choisir</option>${alive.map((player) => `<option value="${player.id}">${escapeHtml(player.name)}</option>`).join("")}`;
  const instruction = game.vote.mode === "simple"
    ? "Faites voter le village, puis sélectionnez directement le joueur désigné."
    : "Demandez à chaque joueur pour qui il vote et reportez chaque voix. Sélectionnez ensuite l’un des joueurs arrivés en tête.";
  return `<section class="${card} p-5 sm:p-6"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Vote du village</p><h2 class="mt-1 font-display text-2xl text-white">Organisez le vote</h2></div><div class="flex rounded-xl border border-white/10 p-1"><button data-action="vote-mode" data-mode="simple" class="rounded-lg px-3 py-2 text-sm ${game.vote.mode === "simple" ? "bg-amberwood text-forest-950" : "text-stone-400"}">Simple</button><button data-action="vote-mode" data-mode="count" class="rounded-lg px-3 py-2 text-sm ${game.vote.mode === "count" ? "bg-amberwood text-forest-950" : "text-stone-400"}">Comptage</button></div></div><div class="mt-5">${mjScript([{ variants: ["Le débat est terminé. Habitants du village, l’heure du vote a sonné. À mon signal, chacun désignera la personne qu’il souhaite voir quitter le village.", "Les paroles s’achèvent et l’heure du jugement arrive. Habitants, préparez votre choix : votre vote décidera qui devra quitter le village aujourd’hui."] }, { action: instruction }], game.day - 1)}</div>
    ${game.vote.mode === "simple" ? `<div class="mt-6">${label("Joueur éliminé", "simple-vote-target")}<select id="simple-vote-target" class="${field}">${opts}</select></div>` : `<div class="mt-6 space-y-2">${alive.map((voter) => `<div class="grid grid-cols-[1fr_auto_1fr] items-center gap-2"><span class="truncate text-sm">${escapeHtml(voter.name)}</span><span class="text-stone-600">→</span><select data-ballot="${voter.id}" aria-label="Vote de ${escapeHtml(voter.name)}" class="${field} !min-h-10 !py-2">${opts.replace(`value="${game.vote.ballots[voter.id] || ""}"`, `value="${game.vote.ballots[voter.id] || ""}" selected`)}</select></div>`).join("")}</div><div class="mt-5 rounded-xl bg-black/20 p-4"><p class="text-sm font-semibold text-white">Classement</p>${result.ranking.length ? `<ol class="mt-2 space-y-1 text-sm text-stone-300">${result.ranking.map(([id, count]) => `<li class="flex justify-between"><span>${escapeHtml(game.players.find((p) => p.id === id)?.name)}</span><strong>${count} voix</strong></li>`).join("")}</ol>` : '<p class="mt-2 text-sm text-stone-500">Aucun vote saisi.</p>'}${result.leaders.length > 1 ? '<p class="mt-3 text-sm text-amber-200">Égalité : choisissez manuellement l’un des joueurs en tête.</p>' : ""}</div><div class="mt-4">${label("Éliminer parmi les joueurs en tête", "count-vote-target")}<select id="count-vote-target" class="${field}"><option value="">Choisir</option>${result.leaders.map((id) => `<option value="${id}">${escapeHtml(game.players.find((p) => p.id === id)?.name)}</option>`).join("")}</select></div>`}
    <div class="mt-6">${btn("Valider l’élimination", "resolve-vote", "danger")}</div></section>`;
}

function timer(game) {
  return `<section class="${card} p-4"><div class="flex items-center gap-3"><span class="text-amberwood">${ICONS.clock}</span><div class="flex-1"><p class="text-xs uppercase tracking-wider text-stone-500">Chronomètre</p><p id="timer-display" class="font-mono text-2xl font-semibold text-white">${formatTime(game.timer.remaining)}</p></div>${btn(game.timer.running ? "Pause" : "Démarrer", game.timer.running ? "pause-timer" : "start-timer", "secondary")} ${btn(ICONS.reset, "reset-timer", "ghost", 'aria-label="Réinitialiser le chronomètre"')}</div></section>`;
}

function dashboard(game, panel = "game") {
  const victory = game.victoryDismissed ? null : game._victory;
  const content = panel === "players" ? `<section class="${card} p-4 sm:p-5"><div class="mb-4 flex items-center justify-between"><h2 class="text-lg font-semibold text-white">Tous les joueurs</h2><span class="text-sm text-stone-500">${game.players.length}</span></div>${playerCards(game)}</section>` : panel === "history" ? historyPanel(game) : panel === "notes" ? notesPanel(game) : `<div class="space-y-5">${phasePanel(game)}${["discussion", "vote"].includes(game.phase) ? timer(game) : ""}</div>`;
  return `<div class="min-h-screen pb-24">${gameHeader(game)}<main class="mx-auto max-w-7xl px-4 py-5 sm:px-6"><div class="mb-5">${stats(game)}</div>${victory ? `<div class="mb-5 rounded-2xl border border-amberwood/40 bg-amberwood/10 p-4"><p class="font-semibold text-amber-100">Condition de victoire potentielle détectée</p><p class="mt-1 text-sm text-stone-300">${victory.label} — ${victory.reason}</p><div class="mt-3 flex gap-2">${btn("Terminer la partie", "end-game")} ${btn("Continuer", "dismiss-victory", "ghost")}</div></div>` : ""}<div class="grid gap-5 lg:grid-cols-[1.08fr_.92fr]"><div>${content}${panel === "game" && !["night-resolution", "wake", "resolution"].includes(game.phase) ? `<div class="mt-3">${btn(`${ICONS.back} Étape précédente`, "previous-phase", "ghost", game.phase === "night" && game.night === 1 ? "disabled" : "")}</div>` : ""}</div><aside class="hidden lg:block"><section class="${card} p-4"><h2 class="mb-4 font-semibold text-white">Joueurs</h2>${playerCards(game)}</section></aside></div></main>${bottomNav(panel)}</div>`;
}

function bottomNav(active) {
  const items = [["game", "Partie", ICONS.moon], ["players", "Joueurs", ICONS.users], ["history", "Historique", ICONS.clock], ["notes", "Notes", ICONS.note]];
  return `<nav aria-label="Navigation de partie" class="fixed inset-x-0 bottom-0 z-30 border-t border-white/10 bg-forest-950/95 px-2 pb-[max(.5rem,env(safe-area-inset-bottom))] pt-2 backdrop-blur"><div class="mx-auto grid max-w-xl grid-cols-4 lg:grid-cols-3">${items.map(([id, text, svg]) => `<button data-action="panel-${id}" class="${id === "players" ? "flex lg:hidden" : "flex"} min-h-14 flex-col items-center justify-center gap-1 rounded-xl text-[11px] ${active === id ? "bg-amberwood/10 text-amberwood" : "text-stone-400 hover:text-white"}">${svg}${text}</button>`).join("")}</div></nav>`;
}

function historyPanel(game) {
  return `<section class="${card} p-5"><div class="mb-4 flex items-center justify-between"><h2 class="text-lg font-semibold text-white">Journal du MJ</h2><span class="text-sm text-stone-500">${game.history.length} événements</span></div><div class="space-y-2">${game.history.length ? game.history.map((event) => `<article class="rounded-xl border border-white/10 bg-black/10 p-3"><div class="flex justify-between gap-3"><p class="text-sm text-parchment">${escapeHtml(event.message)}</p><span class="shrink-0 text-[11px] text-stone-600">${["announcement", "public"].includes(event.visibility) ? "À annoncer" : "Secret MJ"}</span></div><p class="mt-1 text-xs text-stone-500">${event.night ? `Nuit ${event.night}` : `Jour ${event.day}`} · ${PHASE_LABELS[event.phase] || event.phase}</p></article>`).join("") : '<p class="text-sm text-stone-500">Le journal est vide.</p>'}</div></section>`;
}

function notesPanel(game) {
  return `<section class="${card} p-5"><h2 class="text-lg font-semibold text-white">Notes du MJ</h2><p class="mt-1 text-sm text-stone-400">Sauvegarde automatique dans votre espace de gestion privé.</p><div class="mt-5">${label("Notes générales", "general-notes")}<textarea id="general-notes" data-change="general-notes" rows="7" class="${field}">${escapeHtml(game.generalNotes)}</textarea></div><div class="mt-6 space-y-4">${game.players.map((player) => `<div>${label(escapeHtml(player.name), `notes-${player.id}`)}<textarea id="notes-${player.id}" data-player-notes="${player.id}" rows="2" class="${field}">${escapeHtml(player.notes)}</textarea></div>`).join("")}</div></section>`;
}

function settings(settings, inGame) {
  const toggle = (key, title, description) => `<label class="flex cursor-pointer items-start gap-3 rounded-xl border border-white/10 p-3"><span class="min-w-0 flex-1"><span class="block font-medium text-white">${title}</span><span class="mt-0.5 block text-sm text-stone-400">${description}</span></span><input type="checkbox" data-setting="${key}" class="mt-1 h-5 w-5" ${settings[key] ? "checked" : ""}></label>`;
  return `<div class="min-h-screen"><header class="border-b border-white/10 px-4 py-4"><div class="mx-auto flex max-w-3xl items-center justify-between">${logo()}${btn("Fermer", inGame ? "close-settings-game" : "go-home", "ghost")}</div></header><main class="mx-auto max-w-3xl px-4 py-8 sm:px-6"><p class="text-sm font-semibold uppercase tracking-[.18em] text-amberwood">Préférences</p><h1 class="mt-2 font-display text-3xl text-white">Paramètres</h1><div class="mt-7 space-y-3">${toggle("animations", "Animations", "Transitions discrètes entre les écrans.")}${toggle("confirmations", "Confirmations", "Demander avant les actions destructrices.")}${toggle("compact", "Affichage compact", "Réduire les espacements des listes.")}${toggle("wolvesCanTargetWolf", "Les Loups peuvent cibler un Loup", "Autorise les cibles du même camp.")}${toggle("witchCanUseBoth", "Deux potions la même nuit", "Autorise la Sorcière à sauver et empoisonner simultanément.")}${toggle("witchCanSaveSelf", "La Sorcière peut se sauver", "Règle optionnelle conservée avec la partie.")}<div class="grid gap-3 sm:grid-cols-2"><div>${label("Révélation de la Voyante", "setting-seer")}<select id="setting-seer" data-setting-value="seerReveal" class="${field}"><option value="role" ${settings.seerReveal === "role" ? "selected" : ""}>Rôle exact</option><option value="team" ${settings.seerReveal === "team" ? "selected" : ""}>Camp uniquement</option></select></div><div>${label("Timer par défaut", "setting-timer")}<select id="setting-timer" data-setting-value="timerDuration" class="${field}">${[60,120,180,300].map((seconds) => `<option value="${seconds}" ${settings.timerDuration === seconds ? "selected" : ""}>${seconds / 60} minute${seconds > 60 ? "s" : ""}</option>`).join("")}</select></div></div></div></main></div>`;
}

function summary(game) {
  const elimination = [...game.players].filter((p) => !p.alive).sort((a,b) => (a.deathRound || 99) - (b.deathRound || 99));
  return `<div class="min-h-screen"><header class="border-b border-white/10 px-4 py-4"><div class="mx-auto max-w-5xl">${logo()}</div></header><main class="mx-auto max-w-5xl px-4 py-10 sm:px-6"><div class="text-center"><p class="text-sm font-semibold uppercase tracking-[.22em] text-amberwood">Partie terminée</p><h1 class="mt-3 font-display text-4xl text-white">${escapeHtml(game.winner?.label || "Fin de partie")}</h1><p class="mt-2 text-stone-400">${escapeHtml(game.winner?.reason || "")}</p></div><section class="mt-9 ${card} overflow-hidden"><div class="grid grid-cols-[1fr_1fr_auto] gap-3 border-b border-white/10 px-4 py-3 text-xs uppercase tracking-wider text-stone-500"><span>Joueur</span><span>Rôle</span><span>Statut</span></div>${game.players.map((player) => `<div class="grid grid-cols-[1fr_1fr_auto] items-center gap-3 border-b border-white/5 px-4 py-3 text-sm"><span class="font-semibold">${escapeHtml(player.name)}</span><span class="text-stone-300">${getRole(player.roleId).name}</span>${statusBadge(player.alive)}</div>`).join("")}</section><div class="mt-6 grid gap-6 md:grid-cols-2"><section class="${card} p-5"><h2 class="font-semibold text-white">Ordre des éliminations</h2><ol class="mt-3 space-y-2 text-sm">${elimination.length ? elimination.map((p) => `<li>${escapeHtml(p.name)} <span class="text-stone-500">— ${escapeHtml(p.deathCause)}</span></li>`).join("") : '<li class="text-stone-500">Aucune élimination</li>'}</ol></section><section class="${card} p-5"><h2 class="font-semibold text-white">Durée</h2><p class="mt-3 text-stone-300">${game.day} jour${game.day > 1 ? "s" : ""} · ${game.night} nuit${game.night > 1 ? "s" : ""}</p></section></div><section class="mt-6 ${card} p-5"><h2 class="font-semibold text-white">Historique complet</h2><div class="mt-3 max-h-80 space-y-2 overflow-y-auto">${game.history.map((event) => `<p class="border-b border-white/5 pb-2 text-sm text-stone-300">${escapeHtml(event.message)}</p>`).join("")}</div></section><div class="mt-8 flex flex-wrap justify-center gap-3">${btn("Exporter la partie", "export-game", "secondary")} ${btn("Nouvelle partie", "new-game")}</div></main></div>`;
}

export function render(state) {
  const { view, game, settings, panel, hasSave } = state;
  if (view === "home") return home(hasSave);
  if (view === "setup") return setup(game);
  if (view === "distribution") return distribution(game, state.manualRoleSelection);
  if (view === "settings") return settings(game?.settings || settings, Boolean(game?.status === "active"));
  if (view === "summary") return summary(game);
  return dashboard(game, panel);
}

export function menuModal(game) {
  const menuButton = (label, action, svg, description) => `<button type="button" data-action="${action}" class="group flex min-h-14 w-full items-center gap-3 rounded-xl border border-white/10 bg-black/10 px-3.5 py-3 text-left transition hover:border-white/20 hover:bg-white/[.06] focus:outline-none focus:ring-2 focus:ring-amberwood/60"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-white/[.05] text-stone-300 transition group-hover:bg-amberwood/10 group-hover:text-amberwood">${svg}</span><span class="min-w-0 flex-1"><span class="block text-sm font-semibold text-parchment">${label}</span><span class="mt-0.5 block text-xs text-stone-500">${description}</span></span><span class="text-stone-600 transition group-hover:translate-x-0.5 group-hover:text-stone-400">${ICONS.arrow}</span></button>`;
  return `<div><div class="space-y-2">${menuButton("Annuler la dernière action", "undo", ICONS.undo, "Revenir sur la dernière modification")}${menuButton("Exporter la partie", "export-game", ICONS.download, "Télécharger une copie de la sauvegarde")}${menuButton("Paramètres", "open-settings", ICONS.settings, "Modifier les règles et l’affichage")}${menuButton("Retour à l’accueil", "go-home", ICONS.home, "Quitter le tableau de bord sans supprimer la partie")}</div><div class="my-5 h-px bg-white/10"></div><button type="button" data-action="delete-save" class="group flex min-h-14 w-full items-center gap-3 rounded-xl border border-red-900/50 bg-red-950/15 px-3.5 py-3 text-left transition hover:border-red-700/70 hover:bg-wolf/25 focus:outline-none focus:ring-2 focus:ring-red-500/60"><span class="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-wolf/25 text-red-300">${ICONS.trash}</span><span class="min-w-0 flex-1"><span class="block text-sm font-semibold text-red-100">Supprimer la sauvegarde</span><span class="mt-0.5 block text-xs text-red-300/60">Effacer définitivement cette partie</span></span></button></div>`;
}

export function playerModal(player) {
  const role = getRole(player.roleId);
  const roleOptions = ROLES.map((item) => `<option value="${item.id}" ${item.id === player.roleId ? "selected" : ""}>${item.name}</option>`).join("");
  const statusAction = player.alive
    ? `<section class="rounded-2xl border border-red-900/45 bg-red-950/15 p-4"><div class="flex items-start gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-wolf/25 text-red-300">${ICONS.skull}</span><div><h3 class="font-semibold text-red-100">Élimination manuelle</h3><p class="mt-1 text-sm leading-relaxed text-stone-400">Déclarez ce joueur mort en dehors du déroulé normal. L’action sera ajoutée au journal.</p></div></div><button type="button" data-action="kill-player" data-id="${player.id}" class="mt-4 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl border border-red-700/60 bg-gradient-to-r from-wolf/70 to-red-900/60 px-4 py-3 font-semibold text-red-50 shadow-lg shadow-black/15 transition hover:from-red-800 hover:to-red-900 focus:outline-none focus:ring-2 focus:ring-red-500/70">${ICONS.skull}<span>Tuer manuellement</span></button></section>`
    : `<section class="rounded-2xl border border-moss/30 bg-moss/[.06] p-4"><div class="flex items-start gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-moss/10 text-moss">${ICONS.plus}</span><div><h3 class="font-semibold text-[#c9d9c3]">Corriger le statut</h3><p class="mt-1 text-sm leading-relaxed text-stone-400">Replacez ce joueur parmi les vivants si son élimination était une erreur.</p></div></div><button type="button" data-action="revive-player" data-id="${player.id}" class="mt-4 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl border border-moss/40 bg-moss/15 px-4 py-3 font-semibold text-[#dbe7d7] transition hover:bg-moss/25 focus:outline-none focus:ring-2 focus:ring-moss/60">${ICONS.plus}<span>Ressusciter le joueur</span></button></section>`;
  return `<div class="space-y-5"><div class="flex items-center gap-3 rounded-2xl border border-white/10 bg-black/20 p-4"><span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl ${role.team === "wolves" ? "bg-wolf/20 text-red-300" : "bg-moss/10 text-moss"}">${role.icon}</span><div class="min-w-0"><p class="truncate font-semibold text-white">${escapeHtml(player.name)}</p><p class="mt-0.5 text-sm text-stone-400">${role.name} · ${player.alive ? "Vivant" : "Mort"}</p></div></div><section class="rounded-2xl border border-white/10 bg-black/10 p-4"><div class="mb-4 flex items-start gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-amberwood/10 text-amberwood">${role.icon}</span><div><h3 class="font-semibold text-white">Modifier le rôle</h3><p class="mt-1 text-sm text-stone-400">Choisissez le nouveau rôle attribué à ce joueur.</p></div></div>${label("Nouveau rôle", "modal-role")}<select id="modal-role" class="${field}">${roleOptions}</select><button type="button" data-action="apply-player-role" data-id="${player.id}" class="mt-3 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-amberwood px-4 py-3 font-semibold text-forest-950 shadow-lg shadow-black/15 transition hover:bg-[#d8aa59] focus:outline-none focus:ring-2 focus:ring-amberwood/70 focus:ring-offset-2 focus:ring-offset-forest-900"><span class="grid h-7 w-7 place-items-center rounded-full bg-forest-950/10">${ICONS.check}</span><span>Appliquer le rôle</span></button></section>${statusAction}</div>`;
}

export { btn, field, card };
